package com.example.storytv;
import android.app.Activity;import android.os.Bundle;import android.graphics.*;import android.view.*;import org.json.*;import java.io.*;
public class BookActivity extends Activity {
 final ReadingTimer timer=new ReadingTimer();
 int book,page=-1,count,finishChoice=0; JSONArray pages; Bitmap bitmap; View view;CoverArt covers;ReadingWords reader;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setSystemUiVisibility(5894);book=getIntent().getIntExtra("book",0);try{InputStream in=getAssets().open(book==0?"seed/pages.json":"new/pages.json");ByteArrayOutputStream data=new ByteArrayOutputStream();byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)data.write(buf,0,n);in.close();pages=new JSONArray(data.toString("UTF-8"));count=pages.length();covers=new CoverArt(this);}catch(Exception e){finish();return;}view=new Reader();reader=new ReadingWords(this,view,java.util.Locale.US);setContentView(view);}
 void load() throws Exception {if(bitmap!=null)bitmap.recycle();InputStream in=getAssets().open(pages.getJSONObject(page).getString("image"));bitmap=BitmapFactory.decodeStream(in);in.close();}
 protected void onPause(){super.onPause();if(page>=0 && page<count){timer.pause();if(view!=null)view.invalidate();}if(reader!=null)reader.stop();} protected void onDestroy(){if(reader!=null)reader.close();super.onDestroy();}
 public boolean onKeyDown(int k,KeyEvent e){if(page==-1){if(timer.setupKey(k)){view.invalidate();return true;}if(k==KeyEvent.KEYCODE_DPAD_RIGHT||k==KeyEvent.KEYCODE_MEDIA_NEXT)return true;if(k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_ENTER)timer.start();}if(page==count){if(k==KeyEvent.KEYCODE_BACK||k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_ENTER){finish();}return true;}if(page>=0&&k==KeyEvent.KEYCODE_DPAD_DOWN&&!reader.mode){timer.togglePause();view.invalidate();return true;}if(page>=0&&timer.isPaused()){if(k==KeyEvent.KEYCODE_BACK)finish();return true;}if(page>=0&&reader.key(k))return true;int next=page;if(k==KeyEvent.KEYCODE_DPAD_RIGHT||k==KeyEvent.KEYCODE_MEDIA_NEXT||(page==-1&&(k==KeyEvent.KEYCODE_DPAD_CENTER||k==KeyEvent.KEYCODE_ENTER))){if(page==count-1){timer.finish();StoryProgress.complete(this,"book:"+book);reader.reset();page=count;finishChoice=0;view.invalidate();return true;}next++;}else if(k==KeyEvent.KEYCODE_DPAD_LEFT||k==KeyEvent.KEYCODE_BACK){if(page==-1){finish();return true;}if(page==0){page=-1;view.invalidate();return true;}next--;}else return super.onKeyDown(k,e);page=next;reader.reset();try{load();view.invalidate();}catch(Exception ex){finish();}return true;}
 class Reader extends View{Paint p=new Paint(3);Reader(){super(BookActivity.this);}protected void onDraw(Canvas c){c.save();c.scale(getWidth()/1280f,getHeight()/720f);c.drawColor(0xfff8f7f2);if(page==count){FinishScreen.draw(c,p,false);timer.drawScore(c,p);c.restore();if(StoryMotion.enabled())postInvalidateDelayed(100);return;}if(page==-1){Path clip=new Path();clip.addRoundRect(390,45,890,520,22,22,Path.Direction.CW);c.save();c.clipPath(clip);covers.draw(c,p,78+book,new RectF(390,45,890,520));c.restore();p.setTypeface(Typeface.create("sans-serif-medium",0));p.setTextAlign(Paint.Align.CENTER);p.setColor(0xff20464c);p.setTextSize(40);c.drawText(book==0?"A Tiny Seed":"Everything Looks New!",640,585,p);p.setTextSize(23);p.setColor(0xff638082);timer.drawSetup(c,p);c.restore();return;}timer.drawTimer(c,p);postInvalidateDelayed(1000);p.setTypeface(Typeface.create("sans-serif-medium",0));p.setTextSize(23);p.setColor(0xff435f64);p.setTextAlign(Paint.Align.RIGHT);c.drawText((page+1)+" / "+count,1205,55,p);float scale=Math.min(1120f/bitmap.getWidth(),430f/bitmap.getHeight());float w=bitmap.getWidth()*scale,h=bitmap.getHeight()*scale;c.drawBitmap(bitmap,null,new RectF(640-w/2,75,640+w/2,75+h),p);
 try{reader.draw(c,p,pages.getJSONObject(page).getString("text"),640,545,1100,40,0xff183d42);}catch(Exception ignored){}c.restore();}}
}
